package com.yuegang.zhihui.ai.application;import com.yuegang.zhihui.ai.api.*;import com.yuegang.zhihui.ai.domain.*;import com.yuegang.zhihui.ai.infrastructure.CommerceToolGateway;import com.yuegang.zhihui.ai.infrastructure.CommerceToolGateway.ToolEvidence;import com.yuegang.zhihui.search.api.*;import java.util.*;import java.util.regex.*;import javax.sql.*;import org.springframework.jdbc.core.*;import org.springframework.jdbc.datasource.*;import org.springframework.transaction.support.*;
public final class ChatService{private static final String SYSTEM="你是跨境智汇企业客服。只能依据提供的已审核资料和系统提供的只读工具结果回答；必须标注引用；资料不足时明确拒答；不得生成SQL、修改订单、调整余额或发布知识。";private static final Pattern SKU=Pattern.compile("(?:SKU|商品)[：: #]*(\\d{1,20})",Pattern.CASE_INSENSITIVE),ORDER=Pattern.compile("订单[号ID：: #]*(\\d{1,20})",Pattern.CASE_INSENSITIVE);private final RetrievalGateway retrieval;private final ModelGateway model;private final CommerceToolGateway tools;private final JdbcTemplate jdbc;private final TransactionTemplate tx;public ChatService(RetrievalGateway r,ModelGateway m,CommerceToolGateway tools,DataSource d){retrieval=r;model=m;this.tools=tools;jdbc=new JdbcTemplate(d);tx=new TransactionTemplate(new DataSourceTransactionManager(d));}public ChatResponse chat(long user,ChatRequest request){List<SearchHit>hits=retrieval.search(request.message(),request.category(),8);List<ToolEvidence>evidence=new ArrayList<>();Matcher sku=SKU.matcher(request.message());if(sku.find())evidence.add(tools.product(sku.group(1)));if(request.includeOwnOrders()){Matcher order=ORDER.matcher(request.message());if(order.find())evidence.add(tools.ownOrder(user,order.group(1)));}boolean professional=request.message().matches(".*(政策|法规|通关|关税|溯源|原产地).*?");if(hits.isEmpty()&&evidence.isEmpty()&&professional)return save(user,request,"当前已审核知识库中没有足够依据，无法可靠回答该专业问题。",List.of(),List.of(),true,"INSUFFICIENT_EVIDENCE");String context=hits.stream().map(h->"["+h.documentId()+"/"+h.chunkId()+"] "+h.title()+"\n"+h.excerpt()).reduce("",(a,b)->a+"\n"+b);String toolContext=evidence.stream().map(x->"[只读工具 "+x.name()+"] "+x.resultJson()).reduce("",(a,b)->a+"\n"+b);String answer=model.answer(SYSTEM,"已审核资料：\n"+context+"\n只读业务数据：\n"+toolContext+"\n\n问题："+request.message());List<CitationView>citations=hits.stream().map(h->new CitationView("KNOWLEDGE",h.chunkId(),h.title(),h.excerpt(),null)).toList();return save(user,request,answer,citations,evidence,false,null);}private ChatResponse save(long user,ChatRequest r,String answer,List<CitationView>citations,List<ToolEvidence>tools,boolean refused,String reason){return tx.execute(s->{long conversation=r.conversationId()==null||r.conversationId().isBlank()?next():Long.parseLong(r.conversationId());Integer owned=jdbc.queryForObject("SELECT COUNT(*) FROM ai_conversation WHERE id=? AND user_id=?",Integer.class,conversation,user);if(r.conversationId()!=null&&!r.conversationId().isBlank()&&owned==0)throw new com.yuegang.zhihui.common.core.BusinessException(com.yuegang.zhihui.common.core.ErrorCode.RESOURCE_NOT_FOUND);jdbc.update("INSERT INTO ai_conversation(id,user_id,title) VALUES(?,?,?) ON DUPLICATE KEY UPDATE updated_at=NOW(6)",conversation,user,r.message().substring(0,Math.min(100,r.message().length())));jdbc.update("INSERT INTO ai_message(id,conversation_id,role,content) VALUES(?,?,'USER',?)",next(),conversation,r.message());long message=next();jdbc.update("INSERT INTO ai_message(id,conversation_id,role,content,refused,model_name) VALUES(?,?,'ASSISTANT',?,?,?)",message,conversation,answer,refused,"doubao");int i=0;for(var c:citations)jdbc.update("INSERT INTO ai_citation(message_id,sequence_no,source_type,source_id,title,excerpt,url) VALUES(?,?,?,?,?,?,?)",message,i++,c.sourceType(),c.sourceId(),c.title(),c.excerpt(),c.url());for(var tool:tools)jdbc.update("INSERT INTO ai_tool_call(id,message_id,tool_name,arguments_json,result_digest,status) VALUES(?,?,?,?,?,'SUCCEEDED')",next(),message,tool.name(),tool.argumentsJson(),tool.digest());return new ChatResponse(Long.toString(conversation),Long.toString(message),answer,citations,refused,reason);});}private static long next(){return UUID.randomUUID().getMostSignificantBits()&Long.MAX_VALUE;}}
